mapper.select:
SELECT *
FROM ai_feedback_retest
WHERE execution_status = 0
  AND next_retry_time <= #{now}
ORDER BY next_retry_time ASC, id ASC
LIMIT #{limit}

mapper.update:
UPDATE ai_feedback_retest
SET execution_status = 1,
    processing_time = #{now},
    update_time = #{now}
WHERE id = #{id}
  AND execution_status = 0
  AND next_retry_time <= #{now}

UPDATE ai_feedback_retest
SET execution_status = 2,
    answer = #{answer},
    used_knowledge_ids = #{usedKnowledgeIds},
    processing_time = NULL,
    last_error = NULL,
    update_time = #{now}
WHERE id = #{id}
  AND execution_status = 1
  AND processing_time = #{processingTime}

UPDATE ai_feedback_retest
SET execution_status = 0,
    next_retry_time = #{nextRetryTime},
    processing_time = NULL,
    update_time = #{now}
WHERE execution_status = 1
  AND processing_time <= #{staleBefore}
ORDER BY processing_time ASC, id ASC
LIMIT #{limit}
